 "reviewNote": "1872년 보르게 출생. 1903~1906년 요아호로 북서 항로 처음 통과(이때 네트실리크 이누이트에게 털옷·개썰매 등 극지 생활을 배움). 원래 북극 탐험 계획이었으나 피어리의 북극 도달 소식 뒤 남극으로 바꿈(대원들에게 늦게 알린 점 논란). 4명의 대원과 52마리 개, 썰매 4대로 1911년 12월 14일 남극점 도착 — 스콧보다 약 한 달 앞섬. 스콧 일행은 돌아오는 길에 모두 숨짐, 계획대로 개를 식량으로 쓴 일은 연령 고려해 생략. 1926년 노빌레와 비행선으로 북극 통과, 1928년 6월 노빌레 구조 비행 중 실종.",
